import { test, expect } from '@playwright/test';

test.describe('Filter Tag Removal', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should remove individual filter tag by clicking x icon', async ({ page }) => {
    // Verify initial filter tags are displayed
    const filterTags = page.getByRole('region', { name: /filter tags/i });
    await expect(filterTags).toBeVisible();

    // Verify initial filter count
    const filterCount = page.getByText('Apply filters (0)');
    await expect(filterCount).toBeVisible();

    // Verify initial search results
    const searchResults = page.getByRole('region', { name: /search results/i });
    await expect(searchResults).toBeVisible();

    // Click first filter tag to apply
    const firstFilterTag = page.getByRole('button', { name: /filter by category/i });
    await firstFilterTag.click();

    // Verify filter count is updated
    await expect(filterCount).toContainText('Apply filters (1)');

    // Verify search results are updated
    await expect(searchResults).toContainText('Category: Books');

    // Click x icon to remove filter
    const removeFilterIcon = page.getByRole('button', { name: /remove/i });
    await removeFilterIcon.click();

    // Verify filter count is back to zero
    await expect(filterCount).toContainText('Apply filters (0)');

    // Verify search results are restored
    await expect(searchResults).toContainText('All results');
  });

  test('should handle removing all filter tags and clear search', async ({ page }) => {
    // Apply multiple filters
    const firstFilterTag = page.getByRole('button', { name: /filter by category/i });
    await firstFilterTag.click();

    const secondFilterTag = page.getByRole('button', { name: /filter by author/i });
    await secondFilterTag.click();

    // Verify filter count is updated
    const filterCount = page.getByText('Apply filters (2)');
    await expect(filterCount).toBeVisible();

    // Verify search results are filtered
    const searchResults = page.getByRole('region', { name: /search results/i });
    await expect(searchResults).toContainText('Category: Books');

    // Click x icon on first filter
    const removeFirstFilterIcon = page.getByRole('button', { name: /remove/i });
    await removeFirstFilterIcon.click();

    // Verify filter count is updated
    await expect(filterCount).toContainText('Apply filters (1)');

    // Click x icon on second filter
    const removeSecondFilterIcon = page.getByRole('button', { name: /remove/i });
    await removeSecondFilterIcon.click();

    // Verify filter count is back to zero
    await expect(filterCount).toContainText('Apply filters (0)');

    // Verify search results are restored
    await expect(searchResults).toContainText('All results');

    // Verify search input is cleared
    const searchInput = page.getByLabel(/search/i);
    await expect(searchInput).toHaveValue('');
  });
});
